import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { codecTables } from '../src/index.js';

/** docs/pinned-layouts.json is generated by tools/protocol/pinned-layouts.mjs from the pinned VB6 trees; this keeps it complete. */
const rows = JSON.parse(readFileSync(new URL('../../../docs/pinned-layouts.json', import.meta.url), 'utf8')) as { dir: string; id: number; name: string; status: string }[];

describe('docs/pinned-layouts.json', () => {
  it('classifies every implemented packet (rerun the generator when a codec is added)', () => {
    for (const [side, dir] of [['server', 'S->C'], ['client', 'C->S']] as const) {
      const implemented = Object.values(codecTables[side]).flatMap(table => Object.keys(table).map(Number)).sort((a, b) => a - b);
      expect(rows.filter(r => r.dir === dir).map(r => r.id).sort((a, b) => a - b)).toEqual(implemented);
    }
  });
  it('lists exactly the eight packets that changed after the pin, and no id moved', () => {
    expect(rows.filter(r => r.status.startsWith('DIFFERENT')).map(r => r.id).sort((a, b) => a - b)).toEqual([37, 42, 89, 94, 101, 102, 141, 153]);
    expect(rows.filter(r => r.status === 'ID MISMATCH')).toEqual([]);
  });
});
